def compute_order_amount(age, pipeline, mu, cv, f, L):
    S = 22.0 # OPT_PARAM: {"type":"float","initial":22.0,"min":0.0,"max":60.0}
    demand_scale = 1.0 # OPT_PARAM: {"type":"float","initial":1.0,"min":0.5,"max":1.5}
    burst_mix = 0.5 # OPT_PARAM: {"type":"float","initial":0.5,"min":0.0,"max":1.0}
    life_floor = 0.25 # OPT_PARAM: {"type":"float","initial":0.25,"min":0.0,"max":1.0}
    life_power = 1.4 # OPT_PARAM: {"type":"float","initial":1.4,"min":0.1,"max":6.0}
    fifo_age_boost = 1.0 # OPT_PARAM: {"type":"float","initial":1.0,"min":0.0,"max":2.0}
    credit_scale = 1.0 # OPT_PARAM: {"type":"float","initial":1.0,"min":0.0,"max":2.0}
    uncertainty_adjust = -0.25 # OPT_PARAM: {"type":"float","initial":-0.25,"min":-2.0,"max":2.0}

    m = len(age)
    means = [f * mu, (1.0 - f) * mu]
    total_variance = (mu * cv) * (mu * cv)
    variances = [f * total_variance, (1.0 - f) * total_variance]
    event_rates = [0.0, 0.0]
    event_amounts = [0.0, 0.0]

    for s in range(2):
        M = means[s]
        V = variances[s]
        if M > 0.0:
            a = V / (M * M) - 1.0 / M
            root = (a * a - 1.0) ** 0.5
            b = 1.0 + a + root
            c = 1.0 + a - root
            mixture_weight = 1.0 / b
            success1 = 2.0 / (2.0 + M * b)
            success2 = 2.0 / (2.0 + M * c)
            probability_zero = mixture_weight * success1 + (1.0 - mixture_weight) * success2
            actual_event_rate = 1.0 - probability_zero
            moment_event_rate = (M * M) / (V + M * M)
            event_rate = (1.0 - burst_mix) * actual_event_rate + burst_mix * moment_event_rate
            if event_rate < 0.000001:
                event_rate = 0.000001
            if event_rate > 0.999999:
                event_rate = 0.999999
            event_rates[s] = event_rate
            event_amounts[s] = demand_scale * M / event_rate

    scenario_count = 2 ** (2 * L)
    first_moment = 0.0
    second_moment = 0.0

    for mask in range(scenario_count):
        scenario_weight = 1.0
        x = [0.0] * m
        for i in range(m):
            x[i] = float(age[i])

        for t in range(L):
            fifo_bit = (mask // (2 ** (2 * t))) % 2
            lifo_bit = (mask // (2 ** (2 * t + 1))) % 2

            if fifo_bit == 1:
                scenario_weight = scenario_weight * event_rates[0]
                fifo_demand = event_amounts[0]
            else:
                scenario_weight = scenario_weight * (1.0 - event_rates[0])
                fifo_demand = 0.0

            if lifo_bit == 1:
                scenario_weight = scenario_weight * event_rates[1]
                lifo_demand = event_amounts[1]
            else:
                scenario_weight = scenario_weight * (1.0 - event_rates[1])
                lifo_demand = 0.0

            remaining = fifo_demand
            for i in range(m):
                if remaining > 0.0:
                    if x[i] <= remaining:
                        remaining = remaining - x[i]
                        x[i] = 0.0
                    else:
                        x[i] = x[i] - remaining
                        remaining = 0.0

            remaining = lifo_demand
            for k in range(m):
                i = m - 1 - k
                if remaining > 0.0:
                    if x[i] <= remaining:
                        remaining = remaining - x[i]
                        x[i] = 0.0
                    else:
                        x[i] = x[i] - remaining
                        remaining = 0.0

            x[0] = 0.0
            for i in range(m - 1):
                x[i] = x[i + 1]
            x[m - 1] = 0.0

            if t < L - 1 and t < len(pipeline):
                x[m - 1] = x[m - 1] + float(pipeline[t])

        effective_inventory = 0.0
        for i in range(m):
            relative_life = float(i + 1) / float(m)
            relative_life = relative_life + fifo_age_boost * f * (1.0 - relative_life)
            if relative_life < 0.0:
                relative_life = 0.0
            if relative_life > 1.0:
                relative_life = 1.0
            age_credit = life_floor + (1.0 - life_floor) * (relative_life ** life_power)
            effective_inventory = effective_inventory + age_credit * x[i]

        first_moment = first_moment + scenario_weight * effective_inventory
        second_moment = second_moment + scenario_weight * effective_inventory * effective_inventory

    projected_variance = second_moment - first_moment * first_moment
    if projected_variance < 0.0:
        projected_variance = 0.0
    projected_deviation = projected_variance ** 0.5
    inventory_credit = credit_scale * (first_moment + uncertainty_adjust * projected_deviation)
    if inventory_credit < 0.0:
        inventory_credit = 0.0

    order_amount = S - inventory_credit
    if not (order_amount >= 0.0):
        order_amount = 0.0
    if order_amount > 1000000.0:
        order_amount = 1000000.0
    return float(order_amount)

def compute_order_amount(age, pipeline, mu, cv, f, L):
    import math

    S = 12.0 # OPT_PARAM: {"type":"float","initial":12.0,"min":0.0,"max":60.0}
    W0 = 0.35 # OPT_PARAM: {"type":"float","initial":0.35,"min":0.0,"max":2.0}
    W1 = 0.60 # OPT_PARAM: {"type":"float","initial":0.60,"min":0.0,"max":2.0}
    W2 = 0.80 # OPT_PARAM: {"type":"float","initial":0.80,"min":0.0,"max":2.0}
    W3 = 1.00 # OPT_PARAM: {"type":"float","initial":1.00,"min":0.0,"max":2.0}

    m = len(age)
    if m <= 0:
        return 0.0

    x = [0.0] * m
    for i in range(m):
        value = float(age[i])
        if not math.isfinite(value) or value < 0.0:
            value = 0.0
        x[i] = value

    mf = float(f) * float(mu)
    vf = float(f) * (float(mu) * float(cv)) ** 2
    ml = (1.0 - float(f)) * float(mu)
    vl = (1.0 - float(f)) * (float(mu) * float(cv)) ** 2

    wf = 1.0
    pf1 = 1.0
    pf2 = 1.0
    rf1 = 0.0
    rf2 = 0.0
    if mf > 0.0:
        af = vf / (mf * mf) - 1.0 / mf
        if af < 1.0:
            af = 1.0
        rootf = math.sqrt(max(0.0, af * af - 1.0))
        bf = 1.0 + af + rootf
        cf = 1.0 + af - rootf
        wf = 1.0 / bf
        pf1 = 2.0 / (2.0 + mf * bf)
        pf2 = 2.0 / (2.0 + mf * cf)
        rf1 = 1.0 - pf1
        rf2 = 1.0 - pf2

    wl = 1.0
    pl1 = 1.0
    pl2 = 1.0
    rl1 = 0.0
    rl2 = 0.0
    if ml > 0.0:
        al = vl / (ml * ml) - 1.0 / ml
        if al < 1.0:
            al = 1.0
        rootl = math.sqrt(max(0.0, al * al - 1.0))
        bl = 1.0 + al + rootl
        cl = 1.0 + al - rootl
        wl = 1.0 / bl
        pl1 = 2.0 / (2.0 + ml * bl)
        pl2 = 2.0 / (2.0 + ml * cl)
        rl1 = 1.0 - pl1
        rl2 = 1.0 - pl2

    lead = int(L)
    if lead < 0:
        lead = 0
    if lead > 6:
        lead = 6

    for step in range(6):
        if step >= lead:
            break

        total = 0.0
        for i in range(m):
            total = total + x[i]

        after_demand = [0.0] * m

        if total > 0.0:
            if mf <= 0.0:
                max_fifo_demand = 1
            else:
                max_fifo_demand = int(math.ceil(total))
                if max_fifo_demand < 1:
                    max_fifo_demand = 1

            for demand_f in range(256):
                if demand_f >= max_fifo_demand:
                    break

                if mf <= 0.0:
                    probability_f = 1.0
                else:
                    probability_f = (
                        wf * pf1 * (rf1 ** demand_f)
                        + (1.0 - wf) * pf2 * (rf2 ** demand_f)
                    )

                remaining_f = float(demand_f)
                after_fifo = [0.0] * m
                for i in range(m):
                    available = x[i]
                    if remaining_f >= available:
                        after_fifo[i] = 0.0
                        remaining_f = remaining_f - available
                    else:
                        after_fifo[i] = available - remaining_f
                        remaining_f = 0.0

                cumulative = 0.0
                previous_expected = 0.0
                for reverse_i in range(m):
                    i = m - 1 - reverse_i
                    cumulative = cumulative + after_fifo[i]

                    if ml <= 0.0:
                        expected_cumulative = cumulative
                    else:
                        integer_part = int(math.floor(cumulative))
                        fractional_part = cumulative - float(integer_part)

                        truncated_mean1 = (
                            rl1 * (1.0 - rl1 ** integer_part) / (1.0 - rl1)
                            + fractional_part * rl1 ** (integer_part + 1)
                        )
                        truncated_mean2 = (
                            rl2 * (1.0 - rl2 ** integer_part) / (1.0 - rl2)
                            + fractional_part * rl2 ** (integer_part + 1)
                        )
                        expected_cumulative = cumulative - (
                            wl * truncated_mean1
                            + (1.0 - wl) * truncated_mean2
                        )
                        if expected_cumulative < 0.0:
                            expected_cumulative = 0.0

                    expected_segment = expected_cumulative - previous_expected
                    if expected_segment < 0.0:
                        expected_segment = 0.0
                    after_demand[i] = (
                        after_demand[i] + probability_f * expected_segment
                    )
                    previous_expected = expected_cumulative

        shifted = [0.0] * m
        for i in range(1, m):
            shifted[i - 1] = after_demand[i]

        if step < len(pipeline):
            arrival = float(pipeline[step])
            if not math.isfinite(arrival) or arrival < 0.0:
                arrival = 0.0
            shifted[m - 1] = shifted[m - 1] + arrival

        x = shifted

    weighted_projected_stock = 0.0
    for i in range(m):
        if i == 0:
            weight = W0
        elif i == 1:
            weight = W1
        elif i == 2:
            weight = W2
        else:
            weight = W3
        weighted_projected_stock = weighted_projected_stock + weight * x[i]

    order = S - weighted_projected_stock
    if not math.isfinite(order) or order <= 0.0:
        return 0.0
    return float(order)
